insert into public.site_settings (id, name, role, tagline, hero_supporting_copy, bio, availability_text, email, linkedin_url, github_url, resume_url, footer_copy)
values
  (1, 'Gerikah L. Alday', 'UI/UX Designer & Frontend Developer', 'I design it. Then I build it.', 'I turn thoughtful interfaces into real, working products, bringing design and development into the same conversation.', 'I''m Gerikah, a Computer Engineer who enjoys both designing and building. I bring UI/UX thinking and frontend development together, from shaping an interface to connecting the data behind it.', '', 'aldaygerikah@gmail.com', 'https://www.linkedin.com/in/gerikah-alday/', 'https://github.com/gerikah', '', 'UI/UX Designer. Frontend Developer. Computer Engineer.')
insert into public.projects (id, title, slug, project_number, category, short_description, overview, role, tools, year, project_type, status, live_url, repository_url, cover_image_url, cover_alt, is_published, sort_order, created_at, updated_at)
values
  ('11111111-1111-4111-8111-111111111111', 'Off The Rack', 'off-the-rack', 1, 'E-commerce / Full-stack website', 'A responsive digital storefront for one-of-one and upcycled fashion.', 'A responsive storefront that brings product browsing, categories, availability, and custom inquiries together with Supabase-powered product administration.', 'UI/UX design, frontend development, database/admin integration', array['Next.js', 'TypeScript', 'Supabase', 'Vercel']::text[], null, 'Full-stack website', '', '', '', '/images/off-the-rack/hero.png', 'Off The Rack storefront screens shown in the original project presentation', true, 1, '2026-10-13T00:00:00Z', '2026-10-13T00:00:00Z'),
  ('22222222-2222-4222-8222-222222222222', 'Marci Metzger Homes', 'marci-metzger-homes', 2, 'Real Estate / Homepage redesign', 'An independent redesign that turns a real-estate homepage into a clearer editorial experience.', 'An independent redesign concept for a real-estate homepage, using a responsive single-page layout and an editorial visual system while preserving the provided copy and source photography. This is a concept, not an official client engagement.', 'UI/UX redesign and frontend development', array['HTML', 'CSS', 'JavaScript', 'Node/npm', 'Playwright', 'Vercel']::text[], null, 'Independent redesign concept', '', '', '', '/images/marci/hero.png', 'Marci Metzger Homes independent homepage redesign shown in the original project presentation', true, 2, '2026-10-13T00:00:00Z', '2026-10-13T00:00:00Z')
insert into public.project_sections (id, project_id, section_type, heading, body, sort_order, created_at, updated_at)
values
  ('11111111-1111-4111-8111-111111110101', '11111111-1111-4111-8111-111111111111', 'text', 'A storefront for one-of-one pieces', 'Off The Rack is a digital storefront for one-of-one and upcycled fashion. The experience brings product browsing, product categories, and availability into a responsive website.', 1, '2026-10-13T00:00:00Z', '2026-10-13T00:00:00Z'),
  ('11111111-1111-4111-8111-111111110102', '11111111-1111-4111-8111-111111111111', 'text', 'From browsing to the details', 'The storefront connects product listings and product detail views with a custom inquiry flow. Responsive interfaces carry the experience across screen sizes.', 2, '2026-10-13T00:00:00Z', '2026-10-13T00:00:00Z'),
  ('11111111-1111-4111-8111-111111110103', '11111111-1111-4111-8111-111111111111', 'text', 'The work behind the storefront', 'Next.js and TypeScript support the frontend. Supabase powers product administration and database integration, with Vercel used for deployment. My role covered UI/UX design, frontend development, and the database/admin connection.', 3, '2026-10-13T00:00:00Z', '2026-10-13T00:00:00Z'),
  ('11111111-1111-4111-8111-111111110104', '11111111-1111-4111-8111-111111111111', 'reflection', 'Design meets a working product', 'This project brings interface design, frontend development, and product administration into one responsive storefront. The screenshots and initial wireframe show the interface and the system behind it.', 4, '2026-10-13T00:00:00Z', '2026-10-13T00:00:00Z'),
  ('22222222-2222-4222-8222-222222220101', '22222222-2222-4222-8222-222222222222', 'text', 'An independent point of view', 'This is an independent redesign concept for Marci Metzger Homes, not an official client engagement. The project reworks a real-estate homepage as a clearer editorial experience.', 1, '2026-10-13T00:00:00Z', '2026-10-13T00:00:00Z'),
  ('22222222-2222-4222-8222-222222220102', '22222222-2222-4222-8222-222222222222', 'text', 'Give the content room to breathe', 'The redesign uses an editorial visual system within a responsive single-page homepage. The original provided copy and source photography are preserved.', 2, '2026-10-13T00:00:00Z', '2026-10-13T00:00:00Z'),
  ('22222222-2222-4222-8222-222222220103', '22222222-2222-4222-8222-222222222222', 'text', 'Built for the browser', 'The frontend uses HTML, CSS, and JavaScript, with Node/npm, Playwright, and Vercel in the project toolset. The experience includes accessible interactions and a responsive layout.', 3, '2026-10-13T00:00:00Z', '2026-10-13T00:00:00Z'),
  ('22222222-2222-4222-8222-222222220104', '22222222-2222-4222-8222-222222222222', 'reflection', 'A clearer editorial experience', 'The concept explores how layout, typography, and responsive behavior can reshape a real-estate homepage while retaining its provided content and photography.', 4, '2026-10-13T00:00:00Z', '2026-10-13T00:00:00Z')
