  ('11111111-1111-4111-8111-111111110202', '11111111-1111-4111-8111-111111111111', '/images/off-the-rack/shop.jpg', 'Off The Rack shop page screenshot with product browsing and categories', 'Product browsing and categories.', 'image', 'half', 2, '2026-10-13T00:00:00Z'),
  ('11111111-1111-4111-8111-111111110203', '11111111-1111-4111-8111-111111111111', '/images/off-the-rack/product.jpg', 'Off The Rack product detail page screenshot', 'A closer look at a one-of-one piece.', 'image', 'half', 3, '2026-10-13T00:00:00Z'),
  ('11111111-1111-4111-8111-111111110204', '11111111-1111-4111-8111-111111111111', '/images/off-the-rack/admin.jpg', 'Off The Rack product administration dashboard screenshot', 'Supabase-powered product administration.', 'image', 'full', 4, '2026-10-13T00:00:00Z'),
  ('11111111-1111-4111-8111-111111110205', '11111111-1111-4111-8111-111111111111', '/images/off-the-rack/wireframe.png', 'Initial Off The Rack homepage layout wireframe', 'The initial homepage layout wireframe.', 'image', 'full', 5, '2026-10-13T00:00:00Z'),
  ('22222222-2222-4222-8222-222222220201', '22222222-2222-4222-8222-222222222222', '/images/marci/homepage.png', 'Marci Metzger Homes independent redesign homepage screenshot', 'The independent homepage redesign concept.', 'image', 'full', 1, '2026-10-13T00:00:00Z'),
  ('22222222-2222-4222-8222-222222220202', '22222222-2222-4222-8222-222222222222', '/images/marci/homepage-detail.png', 'Detail view of the Marci Metzger Homes independent homepage redesign', 'Editorial layout with the provided copy and source photography.', 'image', 'full', 2, '2026-10-13T00:00:00Z')
